const originalHtml = "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#101f2e\"><title>Career Radar · Private prototype</title><style>\n@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@500;700;800&display=swap');\n:root{--ink:#132639;--muted:#6a7a82;--green:#246e55;--lime:#c9f585}*{box-sizing:border-box}body{margin:0;background:#f4f6f4;color:var(--ink);font-family:'DM Sans',sans-serif}button,input,select,textarea{font:inherit}button{cursor:pointer}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #76aaf7;outline-offset:2px}.shell{display:grid;grid-template-columns:245px minmax(0,1fr);max-width:1500px;margin:auto;min-height:100vh}.sidebar{background:#102334;color:#f0f6f6;padding:30px 18px;display:flex;flex-direction:column;gap:32px}.brand{font:800 21px Manrope;letter-spacing:-1px;padding:0 9px}.brand i{font-style:normal;color:var(--lime)}.brand em{font:600 9px DM Sans;letter-spacing:1px;color:#a5b7be;margin-left:6px}.nav button{display:block;border:0;background:transparent;color:#b8c8ce;text-align:left;width:100%;padding:14px;border-radius:11px;margin:3px 0;font-weight:700;font-size:13px}.nav button.active,.nav button:hover{background:#293e50;color:white}.nav span{display:inline-block;width:30px;font-size:18px}.aside-note{margin-top:auto;border:1px solid #3a5260;border-radius:14px;padding:15px;font-size:12px;line-height:1.6;color:#bdcbd0}.aside-note strong{color:var(--lime)}main{padding:32px clamp(20px,4vw,68px) 85px;min-width:0}.top{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:31px}.eyebrow{font-size:11px;letter-spacing:2px;color:#53856e;font-weight:800;text-transform:uppercase}.pill{display:inline-block;background:#e2f1e7;color:#287552;padding:9px 13px;border-radius:100px;font-size:10px;font-weight:800;white-space:nowrap}h1{font:800 clamp(28px,4vw,42px)/1.15 Manrope;letter-spacing:-1.5px;margin:8px 0 10px}h2{font:800 19px Manrope;letter-spacing:-.5px}.sub{color:var(--muted);line-height:1.7;font-size:14px;margin:0 0 24px}.hero{display:grid;grid-template-columns:1.5fr 1fr;gap:15px;margin:28px 0 30px}.dark{background:#162e42;color:white;border-radius:22px;padding:28px;min-height:218px}.dark h2{font-size:28px;line-height:1.25;max-width:360px;margin:17px 0 8px}.dark p{color:#b8cbd4;font-size:13px;line-height:1.6}.light{background:#e2f0e8;border-radius:22px;padding:26px;display:flex;flex-direction:column;justify-content:space-between}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.metric b{font:800 29px Manrope;display:block}.metric small{font-size:11px;color:#687f76}.btn{border:0;background:var(--lime);padding:12px 15px;border-radius:10px;font-weight:800;font-size:12px;color:#173126}.btn.outline{background:#fff;border:1px solid #dce5e2}.sectionhead{display:flex;justify-content:space-between;align-items:center;gap:10px;margin:30px 0 16px}.sectionhead h2{margin:0}.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.job{display:flex;flex-direction:column;gap:13px;background:white;border:1px solid #e2e8e6;border-radius:17px;padding:21px;min-width:0}.jobtop{display:flex;justify-content:space-between;align-items:center}.mark{background:#e8f0eb;color:#286b56;border-radius:11px;width:40px;height:40px;display:grid;place-items:center;font:800 17px Manrope}.score{background:#e1f4e8;color:#1d7450;font-weight:800;border-radius:9px;padding:8px 11px}.score.weak{background:#f7ecde;color:#946c2e}.job h3{font:800 16px Manrope;margin:0}.company{color:var(--muted);font-size:12px;margin-top:4px}.tags{display:flex;gap:6px;flex-wrap:wrap}.tags span{font-size:10px;padding:6px 8px;border:1px solid #dfe6e4;border-radius:20px;color:#63737b;font-weight:700}.explain{padding:12px;background:#f3f8f5;border-radius:10px;font-size:12px;line-height:1.55;color:#466559}.risk{font-size:11px;color:#876b45;line-height:1.5}.actions{display:flex;gap:7px;margin-top:auto}.actions button{flex:1;border:1px solid #d6e0dd;border-radius:9px;background:white;padding:10px 4px;font-size:11px;font-weight:800}.actions button:first-child{background:#173443;color:white}.panel{background:#fff;border-radius:19px;border:1px solid #e1e7e5;padding:25px;max-width:850px}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:17px}.field{display:flex;flex-direction:column;gap:7px}.field label{font-size:12px;font-weight:800}.field input,.field select,.field textarea{border:1px solid #d2deda;border-radius:10px;padding:11px;background:white;max-width:100%}.field textarea{min-height:130px;resize:vertical}.field small{font-size:11px;color:#778790;line-height:1.5}.wide{grid-column:1/-1}.callout{padding:15px;background:#f1f7f3;border-radius:12px;color:#426d5a;font-size:12px;line-height:1.7;margin-top:20px}.row{display:flex;gap:9px;align-items:center;flex-wrap:wrap}.hide{display:none!important}.tablewrap{overflow:auto;background:white;border-radius:15px;border:1px solid #dfe7e4}table{border-collapse:collapse;width:100%;font-size:12px}td,th{padding:15px;border-bottom:1px solid #e6ece8;text-align:left}th{color:#748790;background:#f7f9f7;font-size:10px;text-transform:uppercase;letter-spacing:1px}.empty{padding:32px;color:#73818a;text-align:center}.foot{font-size:11px;color:#87969d;margin-top:33px;line-height:1.6}.mobile{display:none}.toast{position:fixed;bottom:25px;left:50%;transform:translateX(-50%);background:#153c30;color:white;padding:12px 17px;border-radius:12px;opacity:0;pointer-events:none;transition:.2s;font-size:12px;z-index:100}.toast.show{opacity:1}@media(max-width:900px){.shell{display:block}.sidebar{display:none}main{padding:22px 18px 100px}.hero{grid-template-columns:1fr}.cards{grid-template-columns:1fr}.fields{grid-template-columns:1fr}.wide{grid-column:auto}.mobile{display:flex;position:fixed;bottom:0;left:0;right:0;justify-content:space-around;background:#102334;padding:13px 4px 20px;z-index:20}.mobile button{background:none;border:0;color:#b5cad1;font-size:11px;font-weight:700}.mobile button.active{color:var(--lime)}.mobile span{display:block;font-size:20px}.sectionhead{align-items:start;flex-direction:column}}\n</style></head><body><div class=\"shell\"><aside class=\"sidebar\"><div class=\"brand\">⌖ career<i>radar</i><em>LABS</em></div><nav class=\"nav\"><button data-view=\"dashboard\" class=\"active\"><span>▦</span> Daily dashboard</button><button data-view=\"profile\"><span>◉</span> Career profile</button><button data-view=\"tracker\"><span>▤</span> Application tracker</button><button data-view=\"settings\"><span>⚙</span> Search preferences</button></nav><div class=\"aside-note\"><strong>● PRIVATE DEMO</strong><br>All employers and jobs are synthetic. Your data stays in this browser. No job application is sent.</div></aside><main><div class=\"top\"><span class=\"eyebrow\">Career intelligence / product prototype</span><span class=\"pill\">● DEMO DATA</span></div><section class=\"view\" id=\"dashboard\"><div class=\"eyebrow\">Your daily advantage</div><h1>Good morning, Alex<span style=\"color:#8cbf79\">.</span></h1><p class=\"sub\">Less searching. Better opportunities. Your career, evaluated on evidence.</p><div class=\"hero\"><div class=\"dark\"><div class=\"eyebrow\" style=\"color:#accfc0\">TODAY'S INTELLIGENCE</div><h2>Find the work that actually fits.</h2><p>Your radar compares job duties against your evidence — with transparent gaps and no invented qualifications.</p><button class=\"btn\" onclick=\"go('profile')\">Review my career profile ↗</button></div><div class=\"light\"><div class=\"eyebrow\">Opportunity overview</div><div class=\"metrics\"><div class=\"metric\"><b id=\"count\">0</b><small>In range</small></div><div class=\"metric\"><b id=\"strong\">0</b><small>Strong fit</small></div><div class=\"metric\"><b id=\"saved\">0</b><small>Saved</small></div></div><div style=\"font-size:12px;color:#547663\">Your matches respond to your salary, radius and contract filters.</div></div></div><div class=\"sectionhead\"><h2>Opportunities worth a look</h2><select id=\"sort\" aria-label=\"Sort opportunities\" style=\"padding:10px;border:1px solid #dce5e0;border-radius:10px\"><option value=\"fit\">Best fit first</option><option value=\"distance\">Nearest first</option><option value=\"salary\">Highest salary</option></select></div><div id=\"cards\" class=\"cards\"></div><p class=\"foot\">Illustrative jobs and salaries only. A live vacancies API and official application verification are planned next.</p></section>\n<section class=\"view hide\" id=\"profile\"><div class=\"eyebrow\">Step 01 / your evidence</div><h1>Your career profile.</h1><p class=\"sub\">Show what you've done, not just your job-title keywords.</p><div class=\"panel\"><div class=\"fields\"><div class=\"field wide\"><label>Upload your CV</label><input id=\"cvfile\" type=\"file\" accept=\".txt,.pdf,.doc,.docx\"><small id=\"filemsg\">This prototype can read .txt files locally. PDF and Word extraction will require the real backend; no selected file is uploaded.</small></div><div class=\"field wide\"><label>Or paste your experience</label><textarea id=\"cvtext\" placeholder=\"Paste your work history and responsibilities here...\"></textarea></div><div class=\"row wide\"><button class=\"btn\" onclick=\"analyse()\">Analyse experience</button><button class=\"btn outline\" onclick=\"loadSample()\">Load synthetic example CV</button></div></div><div class=\"callout\" id=\"analysis\">Load the demonstration CV to see how the initial skill profile works.</div></div></section>\n<section class=\"view hide\" id=\"tracker\"><div class=\"eyebrow\">Your search / one place</div><h1>Application tracker.</h1><p class=\"sub\">Record real vacancies from their official employer pages, distinguish confirmed details from unknowns, and track applications. This remains a browser-local workspace: nothing is submitted to employers.</p><div class=\"panel\" style=\"margin-bottom:20px\"><h2>Add a vacancy to your radar</h2><form id=\"vacancyForm\" class=\"fields\"><div class=\"field\"><label for=\"vacancyTitle\">Job title *</label><input id=\"vacancyTitle\" required placeholder=\"e.g. Learning Coordinator\"></div><div class=\"field\"><label for=\"vacancyEmployer\">Employer *</label><input id=\"vacancyEmployer\" required placeholder=\"Employer name\"></div><div class=\"field wide\"><label for=\"vacancyUrl\">Official vacancy URL *</label><input id=\"vacancyUrl\" type=\"url\" required placeholder=\"https://employer.example/jobs/123\"></div><div class=\"field\"><label for=\"vacancyLocation\">Office location</label><input id=\"vacancyLocation\" placeholder=\"Unconfirmed\"></div><div class=\"field\"><label for=\"vacancySalary\">Advertised salary (£ per year)</label><input id=\"vacancySalary\" type=\"number\" min=\"0\" step=\"500\" placeholder=\"Leave blank if unknown\"></div><div class=\"field\"><label for=\"vacancyContract\">Contract</label><select id=\"vacancyContract\"><option value=\"Unknown\">Unconfirmed</option><option value=\"Permanent\">Permanent</option><option value=\"6+ months FTC\">Fixed term 6+ months</option><option value=\"Under 6 months\">Under 6 months</option></select></div><div class=\"field\"><label for=\"vacancyStatus\">Application status</label><select id=\"vacancyStatus\"><option>To review</option><option>Saved</option><option>Applied</option><option>Interview</option><option>Rejected</option><option>Withdrawn</option></select></div><div class=\"field wide\"><label for=\"vacancyNotes\">Evidence / questions to verify</label><textarea id=\"vacancyNotes\" placeholder=\"Office attendance, salary source, eligibility, closing date, reference...\" style=\"min-height:75px\"></textarea></div><div class=\"row wide\"><button class=\"btn\" type=\"submit\">Add vacancy</button><button class=\"btn outline\" type=\"button\" id=\"exportData\">Export my tracker (.json)</button><button class=\"btn outline\" type=\"button\" id=\"importData\">Import tracker (.json)</button><input id=\"importFile\" type=\"file\" accept=\".json,application/json\" class=\"hide\"></div></form><div class=\"callout\">A saved link is <b>not</b> a verified live vacancy. Verify its status and details on the official employer page; salary, office location and eligibility remain unknown until confirmed.</div></div><h2>My opportunities</h2><div class=\"tablewrap\"><table><thead><tr><th>Opportunity</th><th>Source / facts</th><th>Status</th><th>Action</th></tr></thead><tbody id=\"trackerRows\"></tbody></table></div></section>\n<section class=\"view hide\" id=\"settings\"><div class=\"eyebrow\">Step 02 / your boundaries</div><h1>Search preferences.</h1><p class=\"sub\">Your minimum requirements must be respected, not overridden by a high AI score.</p><div class=\"panel\"><div class=\"fields\"><div class=\"field\"><label>Home area</label><input id=\"location\" value=\"Crawley, UK\"><small>Postal-code geocoding is a future integration.</small></div><div class=\"field\"><label>Minimum salary (£ annually)</label><input id=\"salary\" type=\"number\" min=\"0\" step=\"1000\" value=\"30000\"></div><div class=\"field wide\"><label>Search radius: <span id=\"radiusLabel\">10 miles</span></label><input id=\"radius\" type=\"range\" min=\"5\" max=\"50\" step=\"5\" value=\"10\"><div class=\"row\" style=\"justify-content:space-between;font-size:11px;color:#82918a\"><span>5 miles</span><span>50 miles</span></div></div><div class=\"field\"><label>Working style</label><select id=\"working\"><option value=\"any\">Any</option><option value=\"hybrid\">Hybrid preferred</option><option value=\"remote\">Remote only</option><option value=\"onsite\">On-site preferred</option></select></div><div class=\"field\"><label>Contract</label><select id=\"contract\"><option value=\"all\">Permanent or 6+ months</option><option value=\"permanent\">Permanent only</option></select></div><div class=\"row wide\"><button class=\"btn\" onclick=\"saveSettings()\">Save my preferences</button><button class=\"btn outline\" onclick=\"resetDemo()\">Reset demo</button></div></div><div class=\"callout\">🔔 Planned notification: daily at 08:30 with new evidence-checked vacancies. Real notifications are not active in this prototype.</div></div></section><p class=\"foot\">CAREER RADAR · PRIVATE INTERACTIVE PROTOTYPE · Browser-local demo, no real vacancies or external personal-data transfer.</p></main></div><nav class=\"mobile\"><button data-view=\"dashboard\" class=\"active\"><span>▦</span>Radar</button><button data-view=\"profile\"><span>◉</span>Profile</button><button data-view=\"tracker\"><span>▤</span>Tracker</button><button data-view=\"settings\"><span>⚙</span>Settings</button></nav><div id=\"toast\" role=\"status\" class=\"toast\"></div><script>\nconst KEY='career-radar-v1',base={radius:10,salary:30000,working:'hybrid',contract:'all',location:'Crawley, UK',statuses:{},skills:[],manualJobs:[]};let state={...base};try{state={...base,...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{};if(!Array.isArray(state.manualJobs))state.manualJobs=[];\nconst jobs=[{id:1,title:'Training Operations Coordinator',firm:'Northstar Learning (fictional)',salary:37000,miles:6,loc:'Gatwick',contract:'Permanent',hybrid:true,fit:92,why:'Training logistics, schedules and stakeholder support match the evidence.',risk:'Confirm specialist LMS requirements.'},{id:2,title:'Programme Support Officer',firm:'Horizon Institute (fictional)',salary:34000,miles:9,loc:'Horsham',contract:'Permanent',hybrid:true,fit:88,why:'Meeting coordination, reporting and programme records are relevant.',risk:'Some project finance activities require clarification.'},{id:3,title:'Operations Reporting Analyst',firm:'Westbridge Services (fictional)',salary:39000,miles:18,loc:'Redhill',contract:'Permanent',hybrid:true,fit:84,why:'Excel reporting and operational data quality are strong matches.',risk:'Power BI engineering requirements are unclear.'},{id:4,title:'Business Support Administrator',firm:'Elm & Co (fictional)',salary:31000,miles:4,loc:'Crawley',contract:'Permanent',hybrid:false,fit:78,why:'Accurate records, administration and customer communication are relevant.',risk:'Fully on-site; invoice processing experience is uncertain.'},{id:5,title:'Learning Programme Assistant',firm:'Lattice Group (fictional)',salary:27000,miles:7,loc:'Three Bridges',contract:'9-month FTC',hybrid:true,fit:90,why:'Direct relevance to training coordination.',risk:'Below the default £30k salary floor.'},{id:6,title:'HR Strategy Manager',firm:'Summit Advisory (fictional)',salary:48000,miles:8,loc:'Crawley',contract:'Permanent',hybrid:true,fit:42,why:'Some learning terminology overlaps.',risk:'Requires strategic HR ownership and line management.'},{id:7,title:'Client Services Administrator',firm:'Aster Partners (fictional)',salary:32000,miles:13,loc:'East Grinstead',contract:'Permanent',hybrid:true,fit:81,why:'Client support and regulatory documentation align.',risk:'Sector licensing knowledge must be checked.'}];\nfunction persist(){localStorage.setItem(KEY,JSON.stringify(state))}function toast(s){let x=document.getElementById('toast');x.textContent=s;x.classList.add('show');clearTimeout(window.t);window.t=setTimeout(()=>x.classList.remove('show'),2300)}function go(name){document.querySelectorAll('.view').forEach(x=>x.classList.toggle('hide',x.id!==name));document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===name));if(name==='tracker')renderTracker();window.scrollTo(0,0)}document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view));\nfunction matches(){return jobs.filter(j=>j.miles<=state.radius&&j.salary>=state.salary&&(state.contract!=='permanent'||j.contract==='Permanent')&&(state.working!=='remote'||j.hybrid))}function render(){let list=matches();let sort=document.getElementById('sort').value;list.sort((a,b)=>sort==='distance'?a.miles-b.miles:sort==='salary'?b.salary-a.salary:b.fit-a.fit);document.getElementById('count').textContent=list.length;document.getElementById('strong').textContent=list.filter(j=>j.fit>=80).length;document.getElementById('saved').textContent=Object.values(state.statuses).filter(x=>x==='Saved'||x==='Applied').length;document.getElementById('cards').innerHTML=list.length?list.map(j=>`<article class=\"job\"><div class=\"jobtop\"><span class=\"mark\">${j.firm[0]}</span><span class=\"score ${j.fit<70?'weak':''}\">${j.fit}/100</span></div><div><h3>${j.title}</h3><div class=\"company\">${j.firm} · ${j.loc}</div></div><div class=\"tags\"><span>£${j.salary.toLocaleString('en-GB')}</span><span>${j.miles} mi</span><span>${j.hybrid?'Hybrid':'On-site'}</span><span>${j.contract}</span></div><div class=\"explain\"><b>Evidence fit:</b> ${j.why}</div><div class=\"risk\">⚑ ${j.risk}</div><div class=\"actions\"><button onclick=\"mark(${j.id},'Saved')\">${state.statuses[j.id]==='Saved'?'✓ Saved':'Save'}</button><button onclick=\"mark(${j.id},'Skipped')\">Skip</button><button onclick=\"mark(${j.id},'Applied')\">Applied</button></div></article>`).join(''):'<div class=\"empty\" style=\"grid-column:1/-1\">No fictional jobs meet these settings. Adjust the filters to explore.</div>';renderTracker()}\nfunction mark(id,s){state.statuses[id]=s;persist();render();toast(s==='Applied'?'Marked applied in demo — no application sent':s+' to tracker')}\nfunction esc(v){return String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]))}\nfunction renderTracker(){let demos=jobs.filter(j=>state.statuses[j.id]);let rows=state.manualJobs.map(j=>`<tr><td><b>${esc(j.title)}</b><br><small>${esc(j.employer)} · ${esc(j.location||'Location unconfirmed')}</small><br><small>Real lead · manually entered</small></td><td><a href=\"${esc(j.url)}\" target=\"_blank\" rel=\"noopener noreferrer\">Official vacancy ↗</a><br><small>${j.salary?'£'+Number(j.salary).toLocaleString('en-GB'):'Salary unknown'} · ${esc(j.contract)}</small><br><small>${esc(j.notes||'Live status not verified')}</small></td><td><select aria-label=\"Application status\" onchange=\"updateManual('${esc(j.id)}',this.value)\">${['To review','Saved','Applied','Interview','Rejected','Withdrawn'].map(s=>`<option ${j.status===s?'selected':''}>${s}</option>`).join('')}</select></td><td><button class=\"btn outline\" onclick=\"removeManual('${esc(j.id)}')\">Remove</button></td></tr>`).join('');rows+=demos.map(j=>`<tr><td><b>${esc(j.title)}</b><br><small>${esc(j.firm)} · SAMPLE ONLY</small></td><td>Fictional · ${j.fit}/100 sample fit</td><td>${esc(state.statuses[j.id])}</td><td><button class=\"btn outline\" onclick=\"delete state.statuses[${j.id}];persist();render()\">Clear</button></td></tr>`).join('');document.getElementById('trackerRows').innerHTML=rows||'<tr><td class=\"empty\" colspan=\"4\">No vacancies tracked yet. Add an official employer link above.</td></tr>'}\nfunction updateManual(id,s){let j=state.manualJobs.find(j=>j.id===id);if(j){j.status=s;persist();toast('Status updated locally')}}\nfunction removeManual(id){if(!confirm('Remove this opportunity from your local tracker?'))return;state.manualJobs=state.manualJobs.filter(j=>j.id!==id);persist();renderTracker()}\ndocument.getElementById('vacancyForm').onsubmit=e=>{e.preventDefault();let v=id=>document.getElementById(id).value.trim();let url=v('vacancyUrl');try{let u=new URL(url);if(!['https:','http:'].includes(u.protocol))throw Error('Invalid protocol')}catch{return toast('Enter a valid official vacancy URL')};if(state.manualJobs.some(j=>j.url===url))return toast('This vacancy URL is already tracked');state.manualJobs.unshift({id:'manual-'+Date.now(),title:v('vacancyTitle'),employer:v('vacancyEmployer'),url,location:v('vacancyLocation'),salary:v('vacancySalary'),contract:v('vacancyContract'),status:v('vacancyStatus'),notes:v('vacancyNotes'),added:new Date().toISOString()});persist();e.target.reset();renderTracker();toast('Vacancy saved on this device')};\ndocument.getElementById('exportData').onclick=()=>{let blob=new Blob([JSON.stringify({format:'career-radar-v2',exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='career-radar-tracker.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};\ndocument.getElementById('importData').onclick=()=>document.getElementById('importFile').click();document.getElementById('importFile').onchange=async e=>{let f=e.target.files?.[0];if(!f)return;try{let data=JSON.parse(await f.text());if(data.format!=='career-radar-v2'||!Array.isArray(data.state?.manualJobs)||data.state.manualJobs.length>1000)throw Error('Invalid export');if(!confirm('Replace local Career Radar settings and tracker with this backup?'))return;state={...base,...data.state};persist();populate();render();toast('Tracker imported')}catch{toast('Not a valid Career Radar export')}finally{e.target.value=''}};\nfunction populate(){['radius','salary','working','contract','location'].forEach(k=>document.getElementById(k).value=state[k]);document.getElementById('radiusLabel').textContent=state.radius+' miles'}function saveSettings(){['radius','salary'].forEach(k=>state[k]=Math.max(0,+document.getElementById(k).value||0));['working','contract','location'].forEach(k=>state[k]=document.getElementById(k).value);persist();render();toast('Preferences saved locally');go('dashboard')}document.getElementById('radius').oninput=e=>document.getElementById('radiusLabel').textContent=e.target.value+' miles';document.getElementById('sort').onchange=render;function resetDemo(){state={...base,statuses:{},skills:[],manualJobs:state.manualJobs};persist();populate();render();toast('Demo filters reset; real tracker preserved')}\nconst sample='Programme coordinator with experience supporting professional learning seminars, course scheduling, facilitators and participants. Maintained Excel reports, governance records, customer communications, project trackers and accurate data. Supported stakeholder meetings and operational administration.';function loadSample(){document.getElementById('cvtext').value=sample;analyse()}function analyse(){let s=document.getElementById('cvtext').value.trim();if(!s)return toast('Enter CV text or load the demo');let terms=[['Learning coordination',/train|learning|seminar|course/i],['Programme support',/project|programme|coordinat|tracker/i],['Operational reporting',/excel|report|data/i],['Stakeholder support',/stakeholder|customer|participant|communication/i],['Governance administration',/governance|record|meeting|compliance/i],['Commercial operations',/commercial|supplier|quote|purchas/i]];state.skills=terms.filter(t=>t[1].test(s)).map(t=>t[0]);persist();document.getElementById('analysis').innerHTML='<b>Draft skills to confirm:</b><br>'+state.skills.map(x=>'• '+x).join('<br>')+'<br><br><small>Keyword extraction is only a local prototype. Production AI must validate evidence, responsibilities and seniority; never invent qualifications.</small>';toast('Draft profile analysed locally')}document.getElementById('cvfile').onchange=async e=>{let f=e.target.files?.[0];if(!f)return;if(f.name.toLowerCase().endsWith('.txt')){document.getElementById('cvtext').value=await f.text();document.getElementById('filemsg').textContent='Text file read locally. Click Analyse experience.'}else document.getElementById('filemsg').textContent=f.name+' selected. PDF/Word extraction is not enabled yet. Paste CV text instead.'};populate();render();\n</script></body></html>\n";
const liveHtml = `<section class="view hide" id="live"><div class="eyebrow">Adzuna / UK vacancies</div><h1>Search live vacancies.</h1><p class="sub">Live source listings. Always verify the position is still open before applying.</p><div class="panel"><form class="fields" id="liveForm"><div class="field"><label>Keywords</label><input name="what" value="learning coordinator" maxlength="100" required></div><div class="field"><label>Location</label><input name="where" value="Crawley" maxlength="80" required></div><div class="field"><label>Radius (miles)</label><input name="distance" value="10" type="number" min="1" max="100"></div><div class="field"><label>Minimum salary (£)</label><input name="salary_min" type="number" min="0" max="250000" value="30000"></div><div class="row wide"><button class="btn" type="submit">Search Adzuna</button><small id="liveMessage">A new private API key is required to enable search.</small></div></form><div class="callout">Your API credentials never appear in the browser. Listings are not exclusive or verified open. No application is submitted automatically.</div></div><div class="sectionhead"><h2>Results</h2></div><div class="cards" id="liveResults"></div></section>`;
const addon = `<script>(()=>{const btn='<button data-view="live"><span>⌕</span> Live vacancies</button>';document.querySelector('.sidebar .nav').insertAdjacentHTML('beforeend',btn);document.querySelector('.mobile').insertAdjacentHTML('beforeend',btn);document.querySelectorAll('[data-view="live"]').forEach(b=>b.onclick=()=>go('live'));const form=document.querySelector('#liveForm'),msg=document.querySelector('#liveMessage'),results=document.querySelector('#liveResults');const safe=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));form.onsubmit=async e=>{e.preventDefault();msg.textContent='Searching…';results.innerHTML='';const p=new URLSearchParams(new FormData(form));try{const r=await fetch('/api/jobs?'+p);const data=await r.json();if(!r.ok)throw Error(data.error||'Search failed');msg.textContent=data.results.length+' results · powered by Adzuna';results.innerHTML=data.results.map(j=>'<article class="job"><h3>'+safe(j.title)+'</h3><div class="company">'+safe(j.company)+' · '+safe(j.location)+'</div><div class="tags"><span>'+safe(j.salary_min?'£'+Math.round(j.salary_min).toLocaleString('en-GB'):'Salary not disclosed')+'</span><span>Adzuna</span></div><p class="risk">Check the original listing for availability and conditions.</p><a target="_blank" rel="noopener noreferrer" href="'+(String(j.url).startsWith('https://')?safe(j.url):'#')+'">View listing ↗</a></article>').join('')||'<div class="empty">No results for these filters.</div>';}catch(err){msg.textContent=err.message}}})();</script>`;
const html=originalHtml.replace('<section class="view hide" id="profile">',liveHtml+'<section class="view hide" id="profile">').replace('</body>',addon+'</body>');
export default {async fetch(request,env){const url=new URL(request.url);if(url.pathname==='/api/jobs'){
  if(!env.ADZUNA_APP_ID||!env.ADZUNA_APP_KEY)return Response.json({error:'Adzuna not configured. Rotate the exposed key, then configure the replacement securely.'},{status:503});
  const what=(url.searchParams.get('what')||'').trim().slice(0,100),where=(url.searchParams.get('where')||'').trim().slice(0,80);
  if(!what||!where)return Response.json({error:'Keywords and location are required.'},{status:400});
  const distance=Math.max(1,Math.min(100,Number(url.searchParams.get('distance'))||10)),salary_min=Math.max(0,Math.min(250000,Number(url.searchParams.get('salary_min'))||0));
  const api=new URL('https://api.adzuna.com/v1/api/jobs/gb/search/1');for(const [k,v] of Object.entries({app_id:env.ADZUNA_APP_ID,app_key:env.ADZUNA_APP_KEY,what,where,distance,salary_min,results_per_page:20,'content-type':'application/json'}))api.searchParams.set(k,String(v));
  try{const response=await fetch(api,{signal:AbortSignal.timeout(12000)});if(!response.ok)return Response.json({error:'Adzuna returned HTTP '+response.status},{status:502});const data=await response.json();return Response.json({count:data.count,results:(data.results||[]).map(j=>({title:j.title,company:j.company?.display_name,location:j.location?.display_name,salary_min:j.salary_min,url:j.redirect_url}))},{headers:{'cache-control':'private, max-age=300'}})}catch{return Response.json({error:'Adzuna temporarily unavailable.'},{status:502})}
}if(url.pathname!=='/')return new Response('Not found',{status:404});return new Response(html,{headers:{'content-type':'text/html; charset=utf-8','cache-control':'no-store'}})}};
